function validate([s, words]) {
  if (s.length < 1 || s.length > 10000) return 's needs 1 to 10000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase letters.';
  if (words.length < 1 || words.length > 5000) return 'words needs 1 to 5000 strings.';
  const size = words[0].length;
  if (size < 1 || size > 30) return 'Each word has 1 to 30 letters.';
  if (words.some(w => w.length !== size)) return 'All words must have the same length.';
  if (words.some(w => !/^[a-z]+$/.test(w))) return 'Words use only lowercase letters.';
  return null;
}

