function findSubstring(s, words) {
  const wordLength = words[0].length;
  const wordCount = words.length;
  const need = new Map();
  for (const word of words) {
    need.set(word, (need.get(word) || 0) + 1);
  }
  const result = [];

  for (let offset = 0; offset < wordLength; offset++) {
    const seen = new Map();
    let left = offset;
    let matched = 0;

    for (let right = offset; right + wordLength <= s.length; right += wordLength) {
      const word = s.slice(right, right + wordLength);
      if (!need.has(word)) {
        seen.clear();
        matched = 0;
        left = right + wordLength;
        continue;
      }
      seen.set(word, (seen.get(word) || 0) + 1);
      matched++;
      while (seen.get(word) > need.get(word)) {
        const first = s.slice(left, left + wordLength);
        seen.set(first, seen.get(first) - 1);
        matched--;
        left += wordLength;
      }
      if (matched === wordCount) {
        result.push(left);
        const first = s.slice(left, left + wordLength);
        seen.set(first, seen.get(first) - 1);
        matched--;
        left += wordLength;
      }
    }
  }
  return result;
}

