function findSubstring(s, words) {
  const size = words[0].length;
  const total = size * words.length;
  const target = [...words].sort().join(',');
  const found = [];
  for (let start = 0; start + total <= s.length; start++) {
    const pieces = [];
    for (let k = 0; k < words.length; k++) pieces.push(s.substr(start + k * size, size));
    if (pieces.sort().join(',') === target) found.push(start);
  }
  return found;
}

