function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = large || rand() < 0.5 ? 'ab' : 'abc';
  const wordLength = large ? 3 : 1 + pick(3);
  const count = large ? 200 + pick(100) : 1 + pick(4);
  const word = () => Array.from({ length: wordLength }, () => letters[pick(letters.length)]).join('');
  const words = Array.from({ length: count }, word);
  const target = large ? 10000 : 1 + pick(24);
  let s = '';
  while (s.length < target) {
    const r = rand();
    if (r < 0.35) {
      const order = [...words];
      for (let i = order.length - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
      s += order.join('');
    } else if (r < 0.75) s += word();
    else s += letters[pick(letters.length)];
  }
  return [s.slice(0, target), words];
}
